1	{% extends "base.html" %}
2	{% block title %}{{ game.title }} — MetaPulse{% endblock %}
3	
4	{% macro summary_block(summary, title, subtitle) %}
5	<section class="summary">
6	  <h3>{{ title }}</h3>
7	  {% if summary %}
8	    {% if summary.tl_dr %}<p class="tldr">{{ summary.tl_dr }}</p>{% endif %}
9	    <div class="likes">
10	      <div class="likes-col">
11	        <h4 class="pos">Что нравится</h4>
12	        {% if summary.likes %}
13	          <ul>{% for item in summary.likes %}<li>{{ item }}</li>{% endfor %}</ul>
14	        {% else %}<p class="muted">—</p>{% endif %}
15	      </div>
16	      <div class="likes-col">
17	        <h4 class="neg">Что не нравится</h4>
18	        {% if summary.dislikes %}
19	          <ul>{% for item in summary.dislikes %}<li>{{ item }}</li>{% endfor %}</ul>
20	        {% else %}<p class="muted">—</p>{% endif %}
21	      </div>
22	    </div>
23	    <p class="summary-foot muted">
24	      По {{ summary.source_review_count or 0 }} отзывам · модель {{ summary.model or '—' }}
25	      · обновлено {{ summary.updated_at | date_ru }}
26	    </p>
27	  {% else %}
28	    <p class="muted">{{ subtitle }}</p>
29	  {% endif %}
30	</section>
31	{% endmacro %}
32	
33	{% block content %}
34	<p class="breadcrumb"><a href="/">← К каталогу</a></p>
35	
36	<article class="game">
37	  <header class="game-head">
38	    <div class="game-cover">
39	      {% if game.cover_url %}
40	        <img src="{{ game.cover_url }}" alt="{{ game.title }}">
41	      {% else %}
42	        <div class="cover-stub">нет обложки</div>
43	      {% endif %}
44	    </div>
45	
46	    <div class="game-info">
47	      <h1 class="game-title">{{ game.title }}</h1>
48	      <dl class="facts">
49	        {% if game.developer %}<dt>Разработчик</dt><dd>{{ game.developer }}</dd>{% endif %}
50	        {% if game.publisher %}<dt>Издатель</dt><dd>{{ game.publisher }}</dd>{% endif %}
51	        <dt>Дата выхода</dt><dd>{{ game.release_date | date_ru }}</dd>
52	        {% if game.esrb_rating %}<dt>Рейтинг ESRB</dt><dd>{{ game.esrb_rating }}</dd>{% endif %}
53	        {% set genre_list = game.genres | genres %}
54	        {% if genre_list %}<dt>Жанры</dt><dd>{{ genre_list | join(', ') }}</dd>{% endif %}
55	      </dl>
56	
57	      <table class="table scores">
58	        <thead>
59	          <tr><th>Платформа</th><th class="num">Metascore</th><th class="num">Userscore</th><th class="num">Отзывов</th></tr>
60	        </thead>
61	        <tbody>
62	          {% for platform in platforms %}
63	          <tr>
64	            <td>
65	              {{ platform.platform_name }}
66	              {% if platform.is_lead %}<span class="chip chip-lead">основная</span>{% endif %}
67	            </td>
68	            <td class="num"><span class="badge sm {{ platform.metascore | score_class }}">{{ platform.metascore | metascore }}</span></td>
69	            <td class="num"><span class="badge sm {{ platform.userscore | score_class(10) }}">{{ platform.userscore | userscore }}</span></td>
70	            <td class="num muted">
71	              {{ platform.metascore_review_count | int_ru }} / {{ platform.userscore_review_count | int_ru }}
72	            </td>
73	          </tr>
74	          {% else %}
75	          <tr><td colspan="4" class="muted">Платформы ещё не загружены</td></tr>
76	          {% endfor %}
77	        </tbody>
78	      </table>
79	      <p class="muted small">В колонке «Отзывов» — критики / игроки.</p>
80	    </div>
81	  </header>
82	
83	  {% if game.description %}
84	  <section class="description">
85	    <h3>Описание</h3>
86	    <p>{{ game.description }}</p>
87	  </section>
88	  {% endif %}
89	
90	  {% if game.trailer_embed_url %}
91	  <section class="trailer">
92	    <h3>{{ game.trailer_title or 'Трейлер' }}</h3>
93	    <div class="video">
94	      <iframe src="{{ game.trailer_embed_url }}" title="{{ game.trailer_title or 'Трейлер' }}"
95	              allowfullscreen loading="lazy"></iframe>
96	    </div>
97	  </section>
98	  {% endif %}
99	
100	  <div class="summaries">
101	    {{ summary_block(critic_summary, 'Резюме отзывов критиков', 'Резюме появится после обработки отзывов LLM.') }}
102	    {{ summary_block(user_summary, 'Резюме отзывов игроков', 'Резюме появится после обработки отзывов LLM.') }}
103	  </div>
104	
105	  {% if letsplay %}
106	  <section class="letsplay">
107	    <h3>Что говорит блогер в летсплее</h3>
108	    {% if letsplay.conclusion %}<p>{{ letsplay.conclusion }}</p>{% endif %}
109	    <p class="muted small">
110	      <a href="{{ letsplay.video_url }}" rel="noreferrer" target="_blank">{{ letsplay.video_title or letsplay.video_url }}</a>
111	      {% if letsplay.channel %} · {{ letsplay.channel }}{% endif %}
112	      {% if letsplay.view_count %} · {{ letsplay.view_count | int_ru }} просмотров{% endif %}
113	      · заключение по транскрипту ({{ letsplay.transcript_source }})
114	    </p>
115	  </section>
116	  {% endif %}
117	
118	  {% if similar %}
119	  <section class="similar">
120	    <h3>Похожие игры</h3>
121	    <ul class="similar-list">
122	      {% for item in similar %}
123	      <li>
124	        <a href="/game/{{ item.slug }}">
125	          {% if item.cover_url %}<img src="{{ item.cover_url }}" alt="{{ item.title }}" loading="lazy">{% endif %}
126	          <span class="similar-title">{{ item.title }}</span>
127	          <span class="badge sm {{ item.lead_metascore | score_class }}">{{ item.lead_metascore | metascore }}</span>
128	        </a>
129	      </li>
130	      {% endfor %}
131	    </ul>
132	  </section>
133	  {% endif %}
134	</article>
135	{% endblock %}
