1	{% extends "base.html" %}
2	{% block title %}Мониторинг — MetaPulse{% endblock %}
3	
4	{% block content %}
5	<div class="monitor-head">
6	  <div>
7	    <h1 class="page-title">Мониторинг обработки</h1>
8	    <p class="muted">Обновляется в реальном времени через SSE. <span id="sse-state" class="chip">подключение…</span></p>
9	  </div>
10	  <div class="run-box">
11	    <label class="sr-only" for="admin-token">Админ-токен</label>
12	    <input class="input" id="admin-token" type="password" placeholder="X-Admin-Token" autocomplete="off">
13	    <button class="btn btn-primary" id="run-btn" type="button">Запустить обработку</button>
14	    <p id="run-result" class="small muted"></p>
15	  </div>
16	</div>
17	
18	<section class="tiles">
19	  <div class="tile"><span class="tile-label">Игр в базе</span><b id="m-games" class="tile-value">{{ stats.games_total }}</b></div>
20	  <div class="tile"><span class="tile-label">Добавлено сегодня</span><b id="m-today" class="tile-value">{{ stats.games_today }}</b></div>
21	  <div class="tile"><span class="tile-label">Отзывов собрано</span><b id="m-reviews" class="tile-value">{{ stats.reviews_total }}</b></div>
22	  <div class="tile"><span class="tile-label">Резюме LLM</span><b id="m-summaries" class="tile-value">{{ stats.summaries_total }}</b></div>
23	  <div class="tile"><span class="tile-label">Летсплеев</span><b id="m-letsplays" class="tile-value">{{ stats.letsplays_with_conclusion }}/{{ stats.letsplays_total }}</b></div>
24	  <div class="tile"><span class="tile-label">Вызовов LLM сегодня</span><b id="m-llm" class="tile-value">{{ stats.llm_calls_today }}</b></div>
25	  <div class="tile"><span class="tile-label">Токенов сегодня</span><b id="m-tokens" class="tile-value">{{ stats.llm_tokens_today }}</b></div>
26	  <div class="tile"><span class="tile-label">Ошибок LLM сегодня</span><b id="m-llm-errors" class="tile-value">{{ stats.llm_errors_today }}</b></div>
27	</section>
28	
29	<div class="monitor-cols">
30	  <section>
31	    <h3>Воркеры</h3>
32	    <div id="workers" class="workers">
33	      {% if stats.workers %}
34	        {% for worker in stats.workers %}
35	          <div class="worker">
36	            <span class="dot live"></span>
37	            <b>{{ worker.worker }}</b>
38	            <span class="muted">{{ worker.state.stage or '—' }}</span>
39	          </div>
40	        {% endfor %}
41	      {% else %}
42	        <p class="muted">Живых воркеров нет. Проверьте, что контейнер <code>worker</code> запущен.</p>
43	      {% endif %}
44	    </div>
45	
46	    <h3>История прогонов</h3>
47	    <div class="tablewrap">
48	      <table class="table" id="runs">
49	        <thead><tr><th>#</th><th>Запуск</th><th>Статус</th><th>Начало</th><th class="num">Игр</th><th class="num">Ошибок</th></tr></thead>
50	        <tbody>
51	          {% for run in stats.runs %}
52	          <tr>
53	            <td>{{ run.id }}</td>
54	            <td>{{ run.trigger }}</td>
55	            <td><span class="chip status-{{ run.status }}" title="{{ run.error or '' }}">{{ run.status }}</span></td>
56	            <td class="small">{{ run.started_at }}</td>
57	            <td class="num">{{ (run.stats or {}).get('selected', 0) }}</td>
58	            <td class="num">{{ (run.stats or {}).get('errors', 0) }}</td>
59	          </tr>
60	          {% else %}
61	          <tr><td colspan="6" class="muted">Прогонов ещё не было</td></tr>
62	          {% endfor %}
63	        </tbody>
64	      </table>
65	    </div>
66	  </section>
67	
68	  <section>
69	    <h3>Лента событий</h3>
70	    <ul id="events" class="events">
71	      {% for event in stats.events %}
72	        <li class="level-{{ event.level }}">
73	          <span class="ev-stage">{{ event.stage or '—' }}</span>
74	          <span class="ev-msg">{{ event.message }}</span>
75	        </li>
76	      {% else %}
77	        <li class="muted">Событий пока нет</li>
78	      {% endfor %}
79	    </ul>
80	  </section>
81	</div>
82	{% endblock %}
83	
84	{% block scripts %}
85	<script>
86	(function () {
87	  const byId = (id) => document.getElementById(id);
88	  const setText = (id, value) => { const el = byId(id); if (el) el.textContent = value; };
89	
90	  function renderStats(s) {
91	    setText('m-games', s.games_total);
92	    setText('m-today', s.games_today);
93	    setText('m-reviews', s.reviews_total);
94	    setText('m-summaries', s.summaries_total);
95	    setText('m-letsplays', s.letsplays_with_conclusion + '/' + s.letsplays_total);
96	    setText('m-llm', s.llm_calls_today);
97	    setText('m-tokens', s.llm_tokens_today);
98	    setText('m-llm-errors', s.llm_errors_today);
99	
100	    const box = byId('workers');
101	    if (box) {
102	      if (!s.workers || !s.workers.length) {
103	        box.innerHTML = '<p class="muted">Живых воркеров нет. Проверьте, что контейнер <code>worker</code> запущен.</p>';
104	      } else {
105	        box.innerHTML = s.workers.map((w) => {
106	          const st = w.state || {};
107	          const progress = (st.processed !== undefined && st.total)
108	            ? ' · ' + st.processed + '/' + st.total : '';
109	          const current = st.current ? ' · ' + st.current : '';
110	          return '<div class="worker"><span class="dot live"></span><b>' + w.worker + '</b>' +
111	                 '<span class="muted">' + (st.stage || '—') + progress + current + '</span></div>';
112	        }).join('');
113	      }
114	    }
115	  }
116	
117	  function pushEvent(payload) {
118	    const list = byId('events');
119	    if (!list) return;
120	    const li = document.createElement('li');
121	    li.className = 'level-' + (payload.level || 'info') + ' fresh';
122	    const stage = document.createElement('span');
123	    stage.className = 'ev-stage';
124	    stage.textContent = payload.stage || '—';
125	    const msg = document.createElement('span');
126	    msg.className = 'ev-msg';
127	    msg.textContent = payload.message || '';
128	    li.append(stage, msg);
129	    list.prepend(li);
130	    while (list.children.length > 40) list.removeChild(list.lastChild);
131	  }
132	
133	  const state = byId('sse-state');
134	  const source = new EventSource('/api/events');
135	  source.addEventListener('open', () => { if (state) { state.textContent = 'онлайн'; state.className = 'chip status-ok'; } });
136	  source.addEventListener('error', () => { if (state) { state.textContent = 'переподключение…'; state.className = 'chip status-partial'; } });
137	  source.addEventListener('stats', (e) => { try { renderStats(JSON.parse(e.data)); } catch (_) {} });
138	  source.addEventListener('task', (e) => { try { pushEvent(JSON.parse(e.data)); } catch (_) {} });
139	
140	  const TOKEN_KEY = 'metapulse-admin-token';
141	  const tokenInput = byId('admin-token');
142	  if (tokenInput) tokenInput.value = localStorage.getItem(TOKEN_KEY) || '';
143	
144	  const btn = byId('run-btn');
145	  if (btn) btn.addEventListener('click', async () => {
146	    const out = byId('run-result');
147	    const token = (tokenInput && tokenInput.value) || '';
148	    localStorage.setItem(TOKEN_KEY, token);
149	    btn.disabled = true;
150	    out.textContent = 'Ставим задачу в очередь…';
151	    try {
152	      const res = await fetch('/api/admin/run', { method: 'POST', headers: { 'X-Admin-Token': token } });
153	      const body = await res.json().catch(() => ({}));
154	      if (res.ok) {
155	        out.textContent = body.status === 'duplicate'
156	          ? 'Такая задача уже в очереди.'
157	          : 'Задача поставлена: ' + (body.job_id || 'ok');
158	      } else if (res.status === 401) {
159	        out.textContent = 'Неверный токен. Значение берётся из ADMIN_TOKEN в .env.';
160	      } else {
161	        out.textContent = 'Не удалось запустить: ' + (body.detail || res.status);
162	      }
163	    } catch (err) {
164	      out.textContent = 'Не удалось запустить: ' + err;
165	    } finally {
166	      btn.disabled = false;
167	    }
168	  });
169	})();
170	</script>
171	{% endblock %}
