1	<div id="game-grid">
2	  <p class="result-count">
3	    {% if total %}Найдено игр: <b>{{ total }}</b>{% else %}Ничего не найдено{% endif %}
4	  </p>
5	
6	  {% if games %}
7	  <ul class="grid">
8	    {% for game in games %}
9	    <li class="card">
10	      <a class="card-link" href="/game/{{ game.slug }}">
11	        <div class="cover">
12	          {% if game.cover_url %}
13	            <img src="{{ game.cover_url }}" alt="{{ game.title }}" loading="lazy">
14	          {% else %}
15	            <div class="cover-stub">нет обложки</div>
16	          {% endif %}
17	          <span class="badge {{ game.lead_metascore | score_class }}">{{ game.lead_metascore | metascore }}</span>
18	        </div>
19	        <div class="card-body">
20	          <h2 class="card-title">{{ game.title }}</h2>
21	          <div class="card-meta">
22	            <span>{{ game.release_date | date_ru }}</span>
23	            {% if game.lead_userscore is not none %}
24	              <span class="dot"></span>
25	              <span class="user-score {{ game.lead_userscore | score_class(10) }}">
26	                {{ game.lead_userscore | userscore }}
27	              </span>
28	            {% endif %}
29	          </div>
30	          {% if game.developer %}<div class="card-dev">{{ game.developer }}</div>{% endif %}
31	          {% set platform_list = game.platforms | list %}
32	          {% if platform_list %}
33	          <div class="chips">
34	            {% for platform in platform_list[:3] %}
35	              <span class="chip">{{ platform.platform_name }}</span>
36	            {% endfor %}
37	            {% if platform_list | length > 3 %}<span class="chip chip-more">+{{ platform_list | length - 3 }}</span>{% endif %}
38	          </div>
39	          {% endif %}
40	        </div>
41	      </a>
42	    </li>
43	    {% endfor %}
44	  </ul>
45	  {% else %}
46	  <div class="empty">
47	    {% if has_filters %}
48	      <p>По этому запросу ничего нет. Попробуйте изменить фильтры.</p>
49	    {% else %}
50	      <p>База пока пуста.</p>
51	      <p class="muted">Игры появятся после первого обхода — он запускается ежечасно
52	        либо вручную кнопкой на странице <a href="/monitor">мониторинга</a>.</p>
53	    {% endif %}
54	  </div>
55	  {% endif %}
56	
57	  {% if total_pages > 1 %}
58	  <nav class="pager">
59	    {% if page > 1 %}
60	      <a class="btn btn-ghost" href="/?{{ base_query }}{% if base_query %}&{% endif %}page={{ page - 1 }}">← Назад</a>
61	    {% endif %}
62	    <span class="pager-info">Страница {{ page }} из {{ total_pages }}</span>
63	    {% if page < total_pages %}
64	      <a class="btn btn-ghost" href="/?{{ base_query }}{% if base_query %}&{% endif %}page={{ page + 1 }}">Вперёд →</a>
65	    {% endif %}
66	  </nav>
67	  {% endif %}
68	</div>
